script:
frappe.ui.form.on('Journal Entry', {
    refresh: function(frm) {
        frm.add_custom_button(__('General Ledger Report'), function() {
            // Define the route to the General Ledger report with filters
            frappe.set_route('query-report', 'General Ledger-Ref No.', {
                company: frm.doc.company,
                from_date: frm.doc.posting_date,
                to_date: frm.doc.posting_date,
                voucher_no: frm.doc.name
            });
        }, __('View Ledger'));
    }
});

frappe.ui.form.on('Sales Invoice', {
    custom_job_number: function(frm) {
        if (frm.doc.custom_job_number) {
            frappe.call({ 
                method: 'frappe.client.get', 
                args: {
                    doctype: "Job Details", 
                    filters: {
                        name: frm.doc.custom_job_number
                    }
                },
                callback: function(r) { 
                    if (r.message) { 
                        frm.clear_table('custom_console_shipment');
                        r.message.console_shipment.forEach(function(item) {
                            // Check if the customer in the Sales Invoice matches the customer in the child table
                            if (item.customer === frm.doc.customer) {
                                var child = frm.add_child('custom_console_shipment'); 
                                child.cn = item.cn; 
                                child.customer = item.customer;
                                child.nopkgs = item.nopkgs;
                                child.pkg_type = item.pkg_type;
                                child.mode_of_delivery = item.mode_of_delivery;
                                child.invoice_no = item.invoice_no;
                                child.payment_type = item.payment_type;
                                child.shipper_name = item.shipper_name;
                                child.sales_person = item.sales_person;
                                child.remarks = item.remarks;
                            }
                        });
                        frm.refresh_field('custom_console_shipment'); 
                    }
                }
            });
        }
    }
});

frappe.ui.form.on('Job Details', {
    company_name: function(frm) {
        if (frm.doc.company === 'SecOnd Company') {
            frm.set_value('naming_series', 'HSMN./.####');
        }
    }
});
